pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value <= address(c).balance / 2); // avoid unexpected revert

        uint256 before = c.depositsCount();

        // skip if sendMoney would revert (e.g., target is this contract)
        (bool success,) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

