            assertTrue(c.depositsCount() == before + 1, "depositsCount should increase by 1 after each sendMoney call");
        } else {
            // if it reverts, depositsCount should not change
            assertTrue(c.depositsCount() == before, "depositsCount should not change when sendMoney reverts");
        }
    }
}

