import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 sendAmount, uint256 sendTo_ignore) public {
        vm.assume(sendAmount > 0 && sendAmount <= address(c).balance);
        // Call sendMoney with the contract itself as target (the buggy path)
        // Pre-fund contract to ensure sufficient balance
        vm.deal(address(c), sendAmount * 2);
        // Record deposits before
        uint prevCount = c.depositsCount();
        // Trigger the mutant behavior: call sendMoney to self (which in mutant does not increase depositsCount)
        // We use call to avoid modifiers; just call sendMoney directly as owner
        // But the contract's sendMoney is onlyOwner, so prank as owner
        address owner = address(this); // owner of deployed contract is test contract
        vm.prank(owner);
        c.sendMoney(address(c), sendAmount);
        // After call, rule: depositsCount stays same (since fallback not triggered)
        // In reference, calling sendMoney to self would also not trigger fallback, but the mutant's withdrawAll also calls sendMoney to self.
        // Actually the difference is: after a call to sendMoney, withdrawAll() returns different value.
        // withdrawAll is a function, not a getter. Let's check its return value via call.
        // withdrawAll() returns nothing, but we can observe balance changes.
        // The property: After sendMoney to self, contract balance decreases by sendAmount (no fallback).
        // So: balance change == -sendAmount.
        // That holds for both, so not a discriminant.
        // The real discriminant: after sendMoney, if we call withdrawAll, the mutant will send balance to itself again, causing different state.
        // But we need a general rule over public getters. Let's define: depositsCount == (address(c).balance == 0 ? prevCount : prevCount). 
        // Hmm, let's think simpler: The mutant makes withdrawAll call sendMoney to self, which does not trigger fallback, so depositsCount unchanged.
        // In reference, withdrawAll calls withdraw which sends to owner, so balance decreases but depositsCount unchanged.
        // Difference appears when we call withdrawAll after a sendMoney. So we should call sendMoney then withdrawAll.
        // Property: c.depositsCount() after calling sendMoney then withdrawAll is equal to c.depositsCount() before those calls (since neither triggers fallback).
        // That holds for both? Actually sendMoney to self does not trigger fallback; withdrawAll in mutant calls sendMoney to self again, still no fallback. In reference, withdrawAll calls withdraw which sends to owner, no fallback. So depositsCount unchanged. Not a difference.
        // The difference: withdrawAll() in mutant sends to contract address via sendMoney (which uses call), while reference uses transfer. The mutant effectively does nothing because sendMoney to self is a no-op? Actually sendMoney uses call, which sends ETH to self; this is allowed and increases balance? No, sending to self does not change balance. So in mutant, withdrawAll does nothing (balance unchanged). In reference, withdraw reduces balance. So after sendMoney, calling withdrawAll: reference balance decreases, mutant stays same.
        // But the property should be over public getters. We can assert: after sendMoney and then withdrawAll, address(c).balance == balanceBefore - sendAmount (reference) vs unchanged (mutant).
        // So final rule: balance after sequence == initialBalance - sendAmount.
        // That holds for reference, fails for mutant because mutant's withdrawAll doesn't send.
        uint balanceBefore = address(c).balance;
        vm.prank(owner);
        c.sendMoney(address(c), sendAmount);
        // Now call withdrawAll
        vm.prank(owner);
        c.withdrawAll();
        uint expected = balanceBefore - sendAmount;
        // In mutant, withdrawAll calls sendMoney to self again, which does nothing, so balance stays = balanceBefore - sendAmount (since only the first sendMoney deducted). Actually wait: first sendMoney to self does reduce balance by sendAmount (since it's a call with value). Then withdrawAll calls sendMoney to self again, which would try to send the entire contract balance to itself, which is a no-op (balance unchanged). So final balance = balanceBefore - sendAmount. That matches reference? Reference withdrawAll sends entire balance to owner, which is balanceBefore - sendAmount (since owner is test contract's address(this)? Actually owner is test contract address which deployed C, so sending to owner sends to test contract, decreasing C's balance to 0). Wait, in reference, after first sendMoney, balance = balanceBefore - sendAmount. Then withdrawAll calls withdraw(balanceBefore - sendAmount) which sends that amount to owner (test contract), leaving C with 0. So reference final balance = 0, mutant = balanceBefore - sendAmount. So rule: final balance == 0 for reference, mutant fails.
        // So property: after any sendMoney and then withdrawAll, c's balance is 0.
        // That holds for reference (withdrawAll empties), fails for mutant (leaves balance).
        assertTrue(address(c).balance == 0);
    }
}

