pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);

        // Set up sender with ETH
        vm.deal(sender, amount);

        // Send money via sendMoney
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("sendMoney(address,uint256)", address(0), 0));

        // If sendMoney reverted, the rule is vacuously true
        if (!success) {
            assertTrue(true);
            return;
        }

        // Rule: After sendMoney, calling withdrawAll() should transfer the entire contract balance to the owner
        uint256 balanceBefore = address(c).balance;
        address owner = c.owner();
        vm.prank(owner);
        uint256 ownerBalanceBefore = address(owner).balance;
        c.withdrawAll();
        uint256 ownerBalanceAfter = address(owner).balance;

        // The owner's balance should increase by exactly the contract balance before withdrawal
        assertTrue(ownerBalanceAfter - ownerBalanceBefore == balanceBefore);
    }
}

